/* Demonstrates the use of pthread_self() to obtain the ID of the executing thread. */
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

// A helper function to print the thread ID (requires casting for portability/printing)
void print_thread_id(const char* context, pthread_t tid) {
    // Casting pthread_t to unsigned long for printing on common systems
    printf("%s Thread ID: %lu\n", context, (unsigned long)tid);
}

void* worker_thread(void* arg) {
    // 1. Get the ID of the currently executing thread (this worker)
    pthread_t self_id = pthread_self();

    print_thread_id("Worker (via self())", self_id);

    // Check if the passed argument matches our ID (for verification)
    if (pthread_equal(*(pthread_t*)arg, self_id)) {
        printf("Worker: ID matches value passed by creator.\n");
    } else {
        fprintf(stderr, "Worker: ID mismatch!\n");
    }

    return NULL;
}

int main() {
    pthread_t worker_tid;
    int result;

    // 2. Create the new thread. The ID is stored in worker_tid.
    result = pthread_create(&worker_tid, NULL, worker_thread, &worker_tid);
    if (result != 0) {
        perror("pthread_create");
        return EXIT_FAILURE;
    }

    // 3. Get the ID of the main thread
    pthread_t main_self_id = pthread_self();
    print_thread_id("Main (via self())", main_self_id);
    print_thread_id("Main (stored worker ID)", worker_tid);

    // 4. Wait for the worker thread to finish
    pthread_join(worker_tid, NULL);

    return EXIT_SUCCESS;
}
